j:jelly.script:
function processOrderNow(isWishListItem) {
	if ($$('.order_buttons .disabled_order_button').length == 0) {
		try {	
			orderItemWidget.orderNow('${jvar_cat_item.isNewOrderNow()}', isWishListItem);
		}
		catch (e) {
			orderItemWidget.g_cart.disableCartButtons(false);
			throw e;
		}
	}
	else
		alert('${gs.getMessage('Please wait - price being updated')}'); 
}

j:jelly.g:evaluate:
var jvar_oi_order_now_button_override = jelly.jvar_sc_order_now_button;
if (!jelly.jvar_cat_item.isUseScLayout())
	jvar_oi_order_now_button_override = !jelly.jvar_cat_item.isNoOrderNow();
if (jelly.jvar_ignore_order_buttons + '' == 'true')
	jvar_oi_order_now_button_override = 'false';
jvar_oi_order_now_button_override;

var jvar_oi_order_item_button_override = jelly.jvar_sc_order_item_button;
if (!jelly.jvar_cat_item.isUseScLayout())
    jvar_oi_order_item_button_override = 'false';
if (jelly.jvar_ignore_order_buttons + '' == 'true')
	jvar_oi_order_item_button_override = 'false';
if(jelly.jvar_cat_item.isNewOrderNow())
	jvar_oi_order_item_button_override = 'false';
jvar_oi_order_item_button_override;

var jvar_oi_add_to_cart_button_override = jelly.jvar_show_add_to_cart_button;
if (jelly.jvar_ignore_add_to_cart_buttons + '' == 'true')
    jvar_oi_add_to_cart_button_override = 'false';
jvar_oi_add_to_cart_button_override;

    	if (jelly.sysparm_cart_name != null ${AND} jelly.sysparm_cart_name == 'saved_items')
		jvar_show_update_cart_button_override = 'false';
	else
    		jvar_show_update_cart_button_override = 'true';
	jvar_show_update_cart_button_override;

var jvar_show_add_to_wish_list_button_override = '' + jelly.jvar_sc_add_to_wish_list_button;
if (jvar_show_add_to_wish_list_button_override == 'true')
	jvar_show_add_to_wish_list_button_override = '' + new global.GlobalServiceCatalogUtil().isWishListEnabled(jelly.sysparm_catalog);
	var reqParentID = jelly.RP.getParameterValue("sysparm_parent_sys_id");
	if (JSUtil.notNil(reqParentID))
		jvar_show_add_to_wish_list_button_override = false;
jvar_show_add_to_wish_list_button_override;
